package com.shipflow.tasks.reviews;
import com.shipflow.events.OutboxService; import com.shipflow.tasks.Task; import com.shipflow.tasks.TaskService; import com.shipflow.tasks.reviews.dto.*; import com.shipflow.users.User; import com.shipflow.users.UserRepository;
import org.springframework.http.HttpStatus; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.server.ResponseStatusException; import java.util.List;
@Service public class TaskReviewService {
 private final TaskService taskService; private final TaskReviewRepository reviews; private final UserRepository users; private final OutboxService outbox;
 public TaskReviewService(TaskService taskService,TaskReviewRepository reviews,UserRepository users,OutboxService outbox){this.taskService=taskService;this.reviews=reviews;this.users=users;this.outbox=outbox;}
 @Transactional public TaskReviewResponse request(Long taskId){Task task=taskService.getAccessibleTask(taskId); User requester=currentUser(); if(taskService.isProjectOwner(task.getProject())) throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"El propietario no puede solicitar la revisión de su propia tarea"); if(reviews.findFirstByTask_IdAndStatusOrderByCreatedAtDesc(taskId,"PENDING").isPresent()) throw new ResponseStatusException(HttpStatus.CONFLICT,"La tarea ya tiene una revisión pendiente"); TaskReview review=reviews.save(new TaskReview(task,requester)); outbox.publishEvent("TASK_REVIEW",review.getId(),"TASK_REVIEW_REQUESTED",payload(review)); return response(review);}
 @Transactional(readOnly=true) public List<TaskReviewResponse> list(Long taskId){taskService.getAccessibleTask(taskId);return reviews.findAllByTask_IdOrderByCreatedAtDesc(taskId).stream().map(this::response).toList();}
 @Transactional public TaskReviewResponse decide(Long reviewId,ReviewDecisionRequest request){TaskReview review=reviews.findById(reviewId).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"No existe la revisión")); Task task=taskService.getAccessibleTask(review.getTask().getId()); if(!taskService.isProjectOwner(task.getProject())) throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Solo el propietario puede resolver revisiones"); if(!"PENDING".equals(review.getStatus())) throw new ResponseStatusException(HttpStatus.CONFLICT,"La revisión ya fue resuelta"); String status=request.status().trim().toUpperCase(); if(!List.of("APPROVED","CHANGES_REQUESTED").contains(status)) throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"El estado debe ser APPROVED o CHANGES_REQUESTED"); User reviewer=currentUser(); review.resolve(reviewer,status,request.comment()); TaskReview saved=reviews.save(review); outbox.publishEvent("TASK_REVIEW",saved.getId(),"TASK_REVIEW_"+status,payload(saved)); return response(saved);}
 private User currentUser(){String email=SecurityContextHolder.getContext().getAuthentication().getName();return users.findByEmail(email).orElseThrow(()->new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Usuario autenticado no encontrado"));}
 private Object payload(TaskReview r){return java.util.Map.of("reviewId",r.getId(),"taskId",r.getTask().getId(),"projectId",r.getTask().getProject().getId(),"requestedById",r.getRequestedBy().getId(),"status",r.getStatus(),"comment",r.getComment()==null?"":r.getComment());}
 private TaskReviewResponse response(TaskReview r){return new TaskReviewResponse(r.getId(),r.getTask().getId(),r.getTask().getTitle(),r.getRequestedBy().getId(),r.getRequestedBy().getName(),r.getReviewedBy()==null?null:r.getReviewedBy().getId(),r.getReviewedBy()==null?null:r.getReviewedBy().getName(),r.getStatus(),r.getComment(),r.getCreatedAt(),r.getReviewedAt());}
}
